sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Malý poster – ako v Table Search */
.movie-poster img {
    width: 150px;      /* nastavíš podľa potreby */
    height: auto;       /* zachová proporcie */
    border-radius: 6px; /* pekný zaoblený roh */
    box-shadow: 0 2px 6px rgba(0,0,0,0.3); /* jemný tieň */
    display: block;
    margin: 0 auto;    /* centrovanie v kolónke */
}

/* Odstrániť pôvodný hero styling */
.movie-poster-tmdb {
    display: none !important;
}

sp_widget.script:
(function () {

  var sysId = $sp.getParameter('sys_id');
  if (!sysId)
    return;

  var gr = new GlideRecord('x_1080820_mvx_movie');
  if (!gr.get(sysId))
    return;

  data.movie = {
    title: gr.getValue('title'),
    originalTitle: gr.getValue('original_title'),
    festivalTitle: gr.getValue('festival_title'),
    releaseDate: gr.getValue('release_date'),
    description: gr.getValue('description'),
    posterUrl: gr.getValue('poster_url'),
    tmdbId: gr.getValue('tmdb_id')
  };

})();
